// Keeps the site search data honest.
//
// site/src/pages/search.astro no longer carries a hand-maintained option table:
// it renders site/src/data/options.json, generated by `nix build
// .#site-search-data` (`just site-data`) from the real marchyo.* option
// declarations via nixosOptionsDoc. This test guards that generated data — the
// same concern the old hand-table guard had (dead `declared:` paths, options
// attributed to the wrong file), now checked against the committed JSON.
//
// Checked here rather than by Astro because this is a claim about the repo, not
// about the page: every `declared` path must exist, and every marchyo.* option
// named must actually be declared in that file.
//
// Run: node tests/site/option-paths-test.js   (also a `nix flake check` check)

"use strict";

const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..", "..");
const dataPath = path.join(root, "site", "src", "data", "options.json");
const options = JSON.parse(fs.readFileSync(dataPath, "utf8"));

let passed = 0;

function test(name, fn) {
  try {
    fn();
  } catch (error) {
    console.error("not ok - " + name);
    console.error(String(error.message).replace(/^/gm, "    "));
    process.exit(1);
  }
  passed++;
  console.log("ok - " + name);
}

// Options carrying a repo-relative `declared` path. The generator rewrites
// declaration paths to repo-relative form (with a matching GitHub blob `url`);
// anything without one can't be checked and is reported separately.
function declaredRows() {
  return options.filter((o) => typeof o.declared === "string" && o.declared.length > 0);
}

test("options.json is parseable and non-empty", () => {
  assert.ok(Array.isArray(options), "options.json is not a JSON array");
  // A silent collapse to a handful would make the checks below vacuous. The
  // generated set is well over a hundred marchyo.* options.
  assert.ok(options.length >= 50, `expected >= 50 options, found ${options.length}`);
});

test("every option carries a declared path", () => {
  const missing = options.filter((o) => !(typeof o.declared === "string" && o.declared.length > 0)).map((o) => o.name);
  assert.deepEqual(missing, [], `options with no declared path:\n  ${missing.join("\n  ")}`);
});

test("every declared path exists in the repo", () => {
  const missing = declaredRows()
    .filter((row) => !fs.existsSync(path.join(root, row.declared)))
    .map((row) => `${row.name} -> ${row.declared}`);
  assert.deepEqual(missing, [], `these declared paths do not exist:\n  ${missing.join("\n  ")}`);
});

test("every declared path really declares the option's namespace", () => {
  const wrong = [];
  for (const row of declaredRows()) {
    const file = path.join(root, row.declared);
    if (!fs.existsSync(file)) continue; // reported by the test above
    // marchyo.users.<name>.email -> the "users" namespace.
    const namespace = row.name.split(".")[1];
    if (!namespace) continue;
    const text = fs.readFileSync(file, "utf8");
    // The declaring file names the namespace somewhere — either the flat form
    // (`marchyo.users`) or nested under a shared `options.marchyo = { users =
    // ...; }` block (how feature-flags.nix declares desktop/development/…).
    const flat = text.includes(`marchyo.${namespace}`);
    const nested =
      text.includes("options.marchyo") && new RegExp(`(^|[^.\\w])${namespace}\\s*(=|\\.)`, "m").test(text);
    if (!flat && !nested) {
      wrong.push(`${row.name} -> ${row.declared} does not declare the ${namespace} namespace`);
    }
  }
  assert.deepEqual(wrong, [], `misattributed options:\n  ${wrong.join("\n  ")}`);
});

console.log("# " + passed + " passed");
